import argparse
import logging
import os
import sys
import tempfile
from pathlib import Path

import datahome

OVERRIDE_VAR = "SCRATCH_STORE_OVERRIDE"


def ensure_writable(folder):
    try:
        folder.mkdir(parents=True)
    except FileExistsError:
        pass
    probe = folder / ".probe"
    try:
        probe.write_text("ok")
        probe.unlink()
        return folder
    except OSError:
        logging.warning("folder not writable, using a scratch folder")
        return Path(tempfile.mkdtemp(prefix="scratch-"))


def resolve_store():
    override = os.getenv(OVERRIDE_VAR)
    if override:
        folder = Path(override)
    else:
        folder = Path(datahome.store_dir(app="scratchbox", owner="acme"))
    return ensure_writable(folder).resolve()


def main(argv=None):
    parser = argparse.ArgumentParser(description="Show the app data folder")
    parser.parse_args(argv)
    print(resolve_store())
    return 0


if __name__ == "__main__":
    logging.basicConfig(format="%(message)s")
    sys.exit(main())

